// === Tab: mySketch.js ===
let particles = [];
let parNum = 1000; // パーティクルの総数
var mySize;

function setup() {
  mySize = max(windowWidth, windowHeight);
	createCanvas(1112, 834);
  colorMode(HSB, 360, 100, 100, 100);
	//Read full documentation at https://github.com/msawired/OPC
  OPC.slider('d_Alpha', 255);
  OPC.toggle('restart', false);  // works like a momentary switch
  /*OPC.palette('palette', ["#eabfcb", "#c191a1", "#a4508b", "#5f0a87", "#2f004f"],
	[
		["#eabfcb", "#c191a1", "#a4508b", "#5f0a87", "#2f004f"],
		["#c3dfe0", "#bcd979", "#9dad6f", "#7d6d61", "#5e574d"],
		["#4464ad", "#a4b0f5", "#f58f29", "#7d4600", "#466995"]
	]);*/
  OPC.color('bg_Color', '#ffffff');
	OPC.color('draw_Color', '#ff0000');
  //OPC.text('my_text', '', 'Enter Title');
  OPC.toggle('screenshot', false);

  for (let i = 0; i < parNum; i++) {
    particles.push(new Particle(random(width), random(height)));
  } // 全部のパーティクルを作る
  background(0, 0, 100, 100);
}

function draw() {
	// OPC toggle works like a momentary switch
	if (screenshot){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    screenshot = false;  // shut off screenshot toggle
	}
	if (restart) {
    reset()
		restart = false
	}
  for (let j = particles.length - 1; j > 0; j--) {
    particles[j].update();
    particles[j].show();
    if (particles[j].finished()) {
      particles.splice(j, 1);
      background(0, 0, 5, 0.1);
    }
  }

	for (let i = particles.length; i < parNum; i++) {
    particles.push(new Particle(random(width), random(height)));
  } // パーティクルを補充
}

function reset(){
	clear();
  background(bg_Color);
}

// === Tab: particle ===
function Particle(x, y) {
  this.x = x;
  this.y = y;
  this.pos = createVector(this.x, this.y);

  this.life = random(1);
	//drawColor.setAlpha(10);
  this.c = draw_Color;
  this.ff = 0;

  this.update = function () {
    this.ff = noise(this.pos.x / 100, this.pos.y / 100) * TWO_PI; // Flow Field
    let mainP = 1200;
    let changeDir = TWO_PI / mainP; // 方向を変わる
    let roundff = round((this.ff / TWO_PI) * mainP); // round ff
    // *** main point *** //
    this.ff = changeDir * roundff; // 新方向

    if (this.ff < 6 && this.ff > 3) {
      this.pos.add(tan(this.ff)*random(1,3), tan(this.ff));
    } else {
      this.pos.sub(sin(this.ff)*random(0.1,1), cos(this.ff));
    }

		stroke(this.c);
  };

  this.show = function () {
    noFill();
    strokeWeight(random(1.25));
    let lx = 20;
    let ly = 20;
    let px = constrain(this.pos.x, lx, width - lx);
    let py = constrain(this.pos.y, ly, height - ly);
    point(px, py);
  };

  this.finished = function () {
    this.life -= random(random(random(random()))) / 10;
	this.life = constrain(this.life, 0, 1);
    if (this.life == 0) {
      return true;
    } else {
      return false;
    }
  };
}

